{"implementation": "def solve(case):
    attempts = case.get("attempts")
    max_attempts = case.get("max_attempts")
    if not isinstance(attempts, list):
        raise ValueError("attempts must be a list")
    if not isinstance(max_attempts, int):
        raise ValueError("max_attempts must be an integer")
    for i, att in enumerate(attempts):
        if not isinstance(att, dict):
            raise ValueError(f"attempt {i} is not a dict")
        for key in ("success", "failure_signature", "reflection"):
            if key not in att:
                raise ValueError(f"attempt {i} missing key '{key}'")
    n = len(attempts)
    if n == 0:
        return {"decision": "continue", "memory_append": None, "next_attempt": 0}
    last = attempts[-1]
    if last["success"]:
        return {"decision": "stop", "memory_append": None, "next_attempt": n}
    repeated = any(a["failure_signature"] == last["failure_signature"] for a in attempts[:-1])
    if n >= max_attempts or repeated:
        return {"decision": "stop", "memory_append": None, "next_attempt": n}
    return {"decision": "continue", "memory_append": {"reflection": last["reflection"], "signature": last["failure_signature"]}, "next_attempt": n}"}
